 				host:           host,
 				sources:        make([]componentstatus.Reporter, 0),
 				previousEvents: make([]*componentstatus.Event, 0),
 			}
 			statusReporter, isStatusReporter := host.(componentstatus.Reporter)
 			if isStatusReporter {
 				c.hostWrapper.addSource(statusReporter)
 			}

